insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('ruaha-tanzania', '05A', 'Ruaha National Park', 'Tanzania', 'One in ten of the world''s lions, wild dogs', 'live', 'verified', 'lion', 'Tanzania — Southern Circuit / Ruaha', '{"safari","adventure","ultra","romance","deepdive"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, 'core', '{"key_facts":["Tanzania''s largest national park (~20,226 km2) and a global lion stronghold - an estimated ~10% of the world''s lions, in some of the largest prides ever recorded (hunt buffalo and even giraffe)","One of East Africa''s best wild-dog destinations - within the 3rd-largest wild-dog population in the world; ~12,000 elephants in the greater ecosystem; a rare East-meets-Southern-Africa transition zone (greater + lesser kudu, sable, roan)","The Great Ruaha River is the dry-season lifeline and focus of game viewing; 570+ birds; remote, uncrowded, mainly fly-in (south-central Tanzania, ~130 km west of Iringa)","US L3 Reconsider Travel - terrorism concern is the Mtwara Region (far southeastern coast, well away); bookable with L3 disclosure + consent; disclose LGBTQ+ targeting; travel with a licensed operator","Best Jun-Oct (dry - game on the river); green season Nov-Apr lush/birdy (some camps close); Ruaha''s signature is the walking safari (+ night drives + fly-camping); no rhino (poached out - four of Big Five)","Sold via Tanzanian safari DMCs + camp consortia 10-20%+ - IATAN/host-gated, CLIA has NO Africa representation; light-aircraft fly-in + TANAPA park fees are pass-through; TZS (~2,633/USD, USD is the safari currency); eVisa; AMREF evac essential (remote interior)"],"safety":{"emergency":"112 / 999","hospital":"Remote deep-interior - medical access by air; AMREF Flying Doctors (~$40 pp/30d) + travel-medical insurance essential; nearest referral Iringa/Dar","advisory_level":"L3","malaria":"present (interior park) - prophylaxis + DEET advised","yellow_fever":"not required direct from US/Europe; mandatory if transiting >12h through a risk country (e.g. Kenya)","activity_note":"L3 DISCLOSE + CONSENT (terrorism concern is the far-southeastern Mtwara Region, well away; disclose LGBTQ+ targeting - same-sex relations criminalized; travel with a licensed operator). Ruaha is a remote fly-in wilderness - AMREF evac + insurance are load-bearing. Walking safari only with armed ranger (single file, downwind, no bright colors); predator-dense driving (keep still/quiet, never on foot near a kill); night drives to vehicle rules","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel to parts of Tanzania Tanzania FCDO advises against all but essential travel to any area within 20km of the Tanzanian border with the Cabo Delgado province of Mozambique, due to attacks by groups linked with Islamic extremism."},{"form":"against all but essential travel","text":"advises against all but essential travel to any area within 20km of the Tanzanian border with the Cabo Delgado province of Mozambique, due to attacks by groups linked with Islamic extremism."}],"url":"https://www.gov.uk/foreign-travel-advice/tanzania","read":"2026-08-19","page_updated":"2026-05-19T15:47:49+01:00"}},"timing":{"peak":"Jun-Oct (dry) - game concentrates on the Great Ruaha River; the premier predator season; book 4-8 mo ahead (few camps)","shoulder":"Nov + late Oct (good rates, softer crowds)","green":"Dec-Apr (rains - lush, superb birding, cheapest; some camps close, roads soften)","booking_lead":"premium camps 4-8 mo for Jun-Oct (limited beds); green 1-3 mo","off_season_specials":"green-season birding + big-cat cubs (Dec-Apr); the southern-circuit combo (Ruaha + Nyerere/Selous) as an uncrowded alternative to the north","event_peaks":"Jul-Oct + Christmas/NY; the dry-season predator spectacle","campaign_start":"Jun-Oct 6-9 mo out (beds scarce); the Ruaha + Nyerere southern-circuit combo by prior Aug-Oct; position as the connoisseur''s uncrowded predator safari for northern-circuit returnees"},"jewels":[{"name":"The lion kingdom","si_tag":"safari","status":"live","tier":"premier","price_band":"camp + park fees","timing":"Jun-Oct peak","draw_rank":1,"hook":"an estimated one in ten of the world''s lions live in Ruaha, in some of the largest prides ever recorded","si":"safari","blurb":"an estimated one in ten of the world''s lions live in Ruaha, in some of the largest prides ever recorded","when":"Jun-Oct peak","commission":"DMC/camp"},{"name":"Wild dogs + a transition-zone roster","si_tag":"safari","status":"live","tier":"premier","price_band":"camp + park fees","timing":"Jun-Oct","draw_rank":2,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"one of the world''s best wild-dog strongholds, plus a rare East-meets-Southern-Africa game list — greater and lesser kudu, sable, roan","si":"safari","blurb":"one of the world''s best wild-dog strongholds, plus a rare East-meets-Southern-Africa game list — greater and lesser kudu, sable, roan","when":"Jun-Oct","commission":"DMC/camp"},{"name":"Walking safari + fly-camping + night drives","si_tag":"globaladv","status":"live","tier":"premier","price_band":"~$60-500/pp","timing":"Jun-Oct","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Ruaha is one of Tanzania''s great walking-safari parks","si":"adventure","blurb":"Ruaha is one of Tanzania''s great walking-safari parks","when":"Jun-Oct","commission":"DMC"},{"name":"Predator research + transition-zone biodiversity","si_tag":"deepdive","status":"future","tier":"premier","price_band":"on application","timing":"Jun-Oct","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Ruaha is a hub of lion and wild-dog conservation science in a globally significant ecosystem, plus a 570-bird list","si":"deepdive","blurb":"Ruaha is a hub of lion and wild-dog conservation science in a globally significant ecosystem, plus a 570-bird list","when":"Jun-Oct","commission":"DMC/specialist"},{"name":"A Jabali Ridge / Mwagusi honeymoon","si_tag":"ultra","status":"live","tier":"luxury","price_band":"~$900-2,500+/night all-in","timing":"standing; peak 4-8 mo","draw_rank":1,"hook":"Asilia''s Jabali Ridge tucked into a kopje above the plains, or Mwagusi''s legendary bush bandas on a sand river","si":"ultra","blurb":"Asilia''s Jabali Ridge tucked into a kopje above the plains, or Mwagusi''s legendary bush bandas on a sand river","when":"standing; peak 4-8 mo","commission":"consortia/Virtuoso + DMC"},{"name":"A Ruaha wilderness honeymoon","si_tag":"romance","status":"live","tier":"luxury","price_band":"on application","timing":"Jun-Oct","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","when":"Jun-Oct","commission":"consortia/host"}],"faq":[{"q":"What''s the real risk to plan for at Ruaha?","a":"Not the parks - the advisory''s concerns are the far-southeastern Mtwara Region (terrorism, far away) and city petty crime, plus a flagged LGBTQ+ targeting concern travelers should weigh (Tanzanian law criminalizes same-sex relations). In Ruaha itself the risks are ordinary safari ones plus remoteness - it''s a fly-in wilderness, so carry AMREF evac + insurance and follow the walking-safari rules.","source":"newsweek.com","si_tag":"safety"},{"q":"Why choose Ruaha over the northern circuit?","a":"For wildness and predators without the crowds - ~10% of the world''s lions in huge prides, one of the world''s best wild-dog populations, big elephant herds and a transition-zone game roster, all in Tanzania''s largest park with a fraction of the vehicles. It''s the connoisseur''s safari, best paired with Nyerere/Selous.","source":"national-parks.org","si_tag":"safari"},{"q":"When is the best time to visit Ruaha?","a":"The dry season, Jun-Oct, when the Great Ruaha River becomes the only water and game - lions, dogs, elephants - concentrates dramatically along it; the green season (Nov-Apr) is lush and superb for birds (570+ species) but some camps close and roads soften.","source":"getsafaritours.com","si_tag":"safari"},{"q":"How do I get to Ruaha, and how long should I stay?","a":"Mostly by light-aircraft fly-in (from Dar, Iringa or as part of a southern-circuit hop); give it 3-4 nights to justify the flight and to do the river drives and a walking safari - it''s not a day-trip park.","source":"getsafaritours.com","si_tag":"safari"},{"q":"Do I need a visa or yellow-fever certificate for Tanzania?","a":"eVisa required - apply on the official portal before departure. Yellow fever is not required direct from the US/Europe, but is mandatory if you transit >12 h through a risk country like Kenya.","source":"tanzania-specialist.com","si_tag":"safety"}],"seo":{"meta_title":"Ruaha National Park Guide: Lions, Wild Dogs, Walking Safaris & Best Time","meta_description":"Plan a Ruaha safari - Tanzania''s largest, wildest and least-crowded park: ~10% of the world''s lions in record prides, one of the world''s best wild-dog populations, walking safaris and the Great Ruaha River - with the US Level-3 advisory, best time (Jun-Oct), the fly-in and where to stay on the southern circuit.","slug":"ruaha-tanzania","primary_keyword":"Ruaha National Park safari","long_tail":["Ruaha lions prides","Ruaha wild dogs","Ruaha walking safari","Ruaha vs Serengeti","is Tanzania safe safari","Ruaha best time to visit","southern circuit Tanzania"],"search_language":"sw","local_keywords":["Ruaha","simba","mbwa mwitu","tembo","mto"],"hreflang":["en","sw"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-08-01"},"booking":{"bin":"book_with_disclosure","level":"L3","codes":["reconsider-travel","mtwara-terrorism-carveout-far","lgbtq-targeting"],"consent_flow":true,"book_suppressed":false,"note":"Tanzania US L3 Reconsider Travel - the terrorism concern is the Mtwara Region (far southeastern coast), well away from Ruaha in the south-central interior. Bookable with L3 disclosure + consent; also disclose the LGBTQ+ targeting consideration (same-sex relations criminalized). Travel with a licensed operator; remote fly-in - AMREF evac essential. Re-verify each cycle."},"si_checklist_25":{"run_date":"2026-08-01","hits":6,"misses":16,"disregarded":3,"note":"Canonical 25-SI list; per the safari-build rule big game/predators is safari (PRIMARY here - lion + wild-dog stronghold), NOT globaladv; walking safari + night drive + fly-camping = globaladv; predator research + transition-zone biodiversity + 570 birds = deepdive; no rhino - poached out (four of Big Five); sports limited to participant; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"safari","name":"safari","status":"live","note":"big-game/predators - ~10% of the world''s lions + a wild-dog stronghold (PRIMARY)"},{"si":"globaladv","name":"adventure","status":"live","note":"walking safari + night drive + fly-camping"},{"si":"ultra","name":"ultra","status":"live","note":"Jabali Ridge / Mwagusi"},{"si":"romance","name":"Romance, Marriages & Honeymoons","status":"live"},{"si":"deepdive","name":"deepdive","status":"future","note":"predator research / transition-zone biodiversity / 570 birds"}],"ultra":[{"name":"Jabali Ridge (Asilia) / Mwagusi - the wilderness-luxury apex","why_ultra":"a kopje-set design lodge and a legendary sand-river camp, deep in Tanzania''s largest park, with walking safaris and private guiding","earning":"consortia/Virtuoso","virtuoso_value_add":true,"mor":"commissionable-rack","tier":"ultra","price_band":"~$1,200-2,500+/night"},{"name":"A private lion-and-wild-dog walking week","why_ultra":"an exclusive-guide safari: river drives for the great prides + walking safaris + a fly-camp night + wild-dog tracking, from an ultra camp","earning":"DMC/consortia","virtuoso_value_add":false,"mor":"commissionable","tier":"ultra","price_band":"on application"},{"name":"The private southern-circuit safari (Ruaha + Nyerere/Selous)","why_ultra":"Tanzania''s wild south flown and privately guided: Ruaha''s predators + Nyerere''s Rufiji boat safaris, far from the northern crowds","earning":"DMC/consortia","virtuoso_value_add":false,"mor":"commissionable","tier":"ultra","price_band":"on application"}],"source_verified":"2026-08-01","hero":{"query":"Ruaha National Park, Tanzania"},"geo":{"lat":-7.7,"lng":34.8333}}'::jsonb, 15),
  ('samburu-kenya', '05A', 'Samburu National Reserve', 'Kenya', 'Northern Kenya''s wild frontier', 'live', 'verified', 'safariJeep', 'Kenya — Samburu / Northern Frontier', '{"safari","ultra","romance","adventure","deepdive","culture"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, 'core', '{"key_facts":["The ''Samburu Special Five'' - Grevy''s zebra (80%+ of the world''s remaining), reticulated giraffe, Beisa oryx, gerenuk, Somali ostrich - arid-country species found ONLY in Kenya''s northern reserves, not the southern parks","~900 elephants + some of Kenya''s best leopard (riverine forest of the Ewaso Ng''iro River); far fewer vehicles than the south - the connoisseur''s Kenya","The Born Free legacy - George + Joy Adamson raised Elsa the lioness here; home of the proud Samburu people (cousins of the Maasai)","US L2 overall BUT far-north border counties (Mandera, Wajir, Garissa; parts of Marsabit/Turkana) are US L4 Do Not Travel - Samburu is NOT among them (mainstream safari zone); ROUTE VIA FLY-IN","Best Jul-Sep + Jan-Feb (dry); 2-3 days ideal, pairs with Laikipia (rhino); sold via Kenya safari DMCs 10-25% - IATAN/host-gated, CLIA has NO Africa representation","KES (~129/USD) + M-Pesa but safari quoted USD; eTA required; malaria prophylaxis advised (chloroquine-resistant); YF only if arriving from a risk country; AMREF Flying Doctors for evac"],"safety":{"emergency":"999 / 112 / 911 (limited response in the remote north); Kenya Red Cross ambulance 1199; AMREF Flying Doctors for bush evac","hospital":"Remote north - AMREF Flying Doctors (~$40 pp/30d) + travel-medical insurance; nearest referral Nanyuki/Nairobi","advisory_level":"L2","malaria":"prophylaxis advised (Samburu qualifies, chloroquine-resistant); DEET at dusk","yellow_fever":"compulsory only if arriving from a risk country; CDC recommends for most","activity_note":"L2 overall + FAR-NORTH L4 CARVE-OUT (Mandera/Wajir/Garissa + parts of Marsabit/Turkana are Do Not Travel - Samburu is NOT among them; route via fly-in, verify current advisory). Dangerous game at close range - stay in the vehicle, follow the guide; camel/bush walks with armed guides. Remote north - carry AMREF evac + insurance","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all travel","text":"advises against all travel to: Mandera County Tarbaj and Wajir East constituencies in Wajir County, except for Wajir Town areas of Wajir County within 60km of Kenya’s border with Somalia Garissa County - except for Garissa Town, the constituency of Lagdera and the areas of Balambala constituency which lie north and west of the main road which runs from Saka on the Tana River up to the intersection with the C81 Road Lamu County, except for Lamu Island and Manda Island FCDO advises against all but essential travel to: Garissa Town Tana River County north of the Tana River as far as the town of Saka within 15km of the east coast between the Tana River and the Galana (Athi-Galana-Sabaki) River Find out more about why FCDO advises against travel ."},{"form":"against all travel","text":"advises against all travel to: Mandera County Tarbaj and Wajir East constituencies in Wajir County, except for Wajir Town areas of Wajir County within 60km of Kenya’s border with Somalia Garissa County - except for Garissa Town, the constituency of Lagdera and the areas of Balambala constituency which lie north and west of the main road which runs from Saka on the Tana River up to the intersection with the C81 Road Lamu County, except for Lamu Island and Manda Island FCDO advises against all but essential travel to: Garissa Town Tana River County north of the Tana River as far as the town of Saka within 15km of the east coast between the Tana River and the Galana (Athi-Galana-Sabaki) River There have been frequent attacks in the north-eastern border regions, most of which were attributed to Al Shabaab."},{"form":"against all but essential travel","text":"advises against all but essential travel to: Garissa Town Tana River County north of the Tana River as far as the town of Saka within 15km of the east coast between the Tana River and the Galana (Athi-Galana-Sabaki) River Find out more about why FCDO advises against travel ."},{"form":"against all but essential travel","text":"advises against all but essential travel to: Garissa Town Tana River County north of the Tana River as far as the town of Saka within 15km of the east coast between the Tana River and the Galana (Athi-Galana-Sabaki) River There have been frequent attacks in the north-eastern border regions, most of which were attributed to Al Shabaab."}],"url":"https://www.gov.uk/foreign-travel-advice/kenya","read":"2026-08-19","page_updated":"2026-06-24T12:48:44+01:00"}},"timing":{"peak":"Jul-Sep (dry, hot, wildlife on the river) + Jan-Feb (dry)","shoulder":"Jun + Oct (good game, softer rates)","green":"Mar-May + Nov (rains - lush, birdlife, quietest, cheapest)","booking_lead":"river lodges + fly-in 3-6 mo (Jul-Sep + Jan-Feb; distinctive lodges are small); shoulder 2-4 mo; green 1-2 mo","off_season_specials":"green-season value + birding; combine Laikipia (rhino) an hour away, or Mara/Amboseli","event_peaks":"Jul-Sep + Christmas/NY + Easter","campaign_start":"Jul-Sep + Jan-Feb Special-Five safaris 4-6 mo out; green birding value by prior Sep-Oct; bundle Samburu + Laikipia (northern-Kenya pairing)"},"jewels":[{"name":"The Samburu Special Five","si_tag":"safari","status":"live","tier":"comfort","price_band":"~$500-2,000/pp/day","timing":"Jul-Sep + Jan-Feb","draw_rank":1,"hook":"Grevy''s zebra, reticulated giraffe, gerenuk, Beisa oryx and Somali ostrich — arid-country species you won''t see in the southern parks","si":"safari","blurb":"Grevy''s zebra, reticulated giraffe, gerenuk, Beisa oryx and Somali ostrich — arid-country species you won''t see in the southern parks","when":"Jul-Sep + Jan-Feb","commission":"safari DMC 10-25%"},{"name":"Leopard + elephants on the Ewaso Ng''iro","si_tag":"safari","status":"live","tier":"comfort","price_band":"~$500-2,000/pp/day","timing":"Jul-Sep  + Jan-Feb","draw_rank":2,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"some of Kenya''s best leopard in the doum-palm riverine forest, plus ~900 elephants and big cats drawn to the river","si":"safari","blurb":"some of Kenya''s best leopard in the doum-palm riverine forest, plus ~900 elephants and big cats drawn to the river","when":"Jul-Sep  + Jan-Feb","commission":"safari DMC 10-25%"},{"name":"A camel safari + bush walk","si_tag":"globaladv","status":"live","tier":"premier","price_band":"~$60-150/pp","timing":"Jul-Sep  + Jan-Feb","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"ride the Samburu country by camel with the warriors, a rare on-foot/on-camel angle among the wildlife and the culture","si":"adventure","blurb":"ride the Samburu country by camel with the warriors, a rare on-foot/on-camel angle among the wildlife and the culture","when":"Jul-Sep  + Jan-Feb","commission":"camp/DMC"},{"name":"The Born Free / Elsa legacy","si_tag":"deepdive","status":"future","tier":"essential","price_band":"on application","timing":"Jul-Sep  + Jan-Feb","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the Adamsons'' country — the story of Elsa the lioness and Born Free, and the conservation lineage it began; a deeper wildlife-heritage layer","si":"deepdive","blurb":"the Adamsons'' country — the story of Elsa the lioness and Born Free, and the conservation lineage it began; a deeper wildlife-heritage layer","when":"Jul-Sep  + Jan-Feb","commission":"DMC/venue"},{"name":"A Samburu village visit","si_tag":"culture","status":"future","tier":"essential","price_band":"~$20-50/pp","timing":"Jul-Sep  + Jan-Feb","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the proud Samburu people — a manyatta visit, warriors'' dances and beadwork with a fair-trade, community-benefiting operator","si":"culture","blurb":"the proud Samburu people — a manyatta visit, warriors'' dances and beadwork with a fair-trade, community-benefiting operator","when":"Jul-Sep  + Jan-Feb","commission":"DMC/community"},{"name":"A river-lodge honeymoon (Saruni / Sasaab)","si_tag":"ultra","status":"live","tier":"luxury","price_band":"~$600-1,600+/night all-in","timing":"standing; peak 3-6 mo","draw_rank":1,"hook":"Samburu''s distinctive lodges — Saruni''s rock-set suites, Sasaab''s Moroccan-Swahili tents over the Ewaso Ng''iro — private, stylish and quiet; honeymoon-grade","si":"ultra","blurb":"Samburu''s distinctive lodges — Saruni''s rock-set suites, Sasaab''s Moroccan-Swahili tents over the Ewaso Ng''iro — private, stylish and quiet; honeymoon-grade","when":"standing; peak 3-6 mo","commission":"consortia/Virtuoso + DMC"},{"name":"A Samburu river honeymoon","si_tag":"romance","status":"live","tier":"luxury","price_band":"on application","timing":"Jul-Sep  + Jan-Feb","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","when":"Jul-Sep  + Jan-Feb","commission":"consortia/host"}],"faq":[{"q":"What''s the real risk to plan for in Samburu?","a":"The northern-frontier context and remoteness. Stick to the licensed-operator reserve programme (fly-in recommended over long northern road transfers), follow your guide with dangerous game, and carry AMREF Flying Doctors (~$40 pp/30 days) + travel-medical insurance - public EMS is limited in the north. Malaria prophylaxis is essential.","source":"cdc.gov","si_tag":"safety"},{"q":"What makes Samburu different from the Mara or Amboseli?","a":"The Special Five - Grevy''s zebra, reticulated giraffe, oryx, gerenuk and Somali ostrich you won''t see in the southern parks - plus top leopard in the riverine forest, elephants on the Ewaso Ng''iro, and far fewer vehicles. It''s the connoisseur''s Kenya.","source":"charmingsafariz.com","si_tag":"safari"},{"q":"When is the best time to visit Samburu?","a":"Jun-Sep and Jan-Feb (dry) - hot and dry, when wildlife concentrates on the river and game-viewing peaks (Jul-Sep is the sweet spot). The green rains bring lush scenery, birdlife and lower rates.","source":"samburureserve.org","si_tag":"safari"},{"q":"How many days do I need in Samburu?","a":"2-3 days is ideal to work the river circuits and find the Special Five plus leopard; it pairs naturally with Laikipia (rhino, an hour''s drive/short hop) or the Mara/Amboseli.","source":"africaunpacked.com","si_tag":"safari"},{"q":"Do I need a visa or yellow-fever certificate for Kenya?","a":"An eTA (Kenya replaced visas with the eTA in 2024 - apply at least 2 weeks ahead). Yellow fever is compulsory only if you arrive from a YF-risk country; CDC recommends the vaccine for most.","source":"cdc.gov","si_tag":"safari"}],"seo":{"meta_title":"Samburu Safari Guide: The Special Five, Leopard, Best Time & Northern-Kenya Safety","meta_description":"Plan a Samburu safari - northern Kenya''s Special Five (Grevy''s zebra, reticulated giraffe, gerenuk, oryx, Somali ostrich), Kenya''s best leopard on the Ewaso Ng''iro, the Born Free legacy and far fewer vehicles - with the fly-in northern-Kenya safety picture, timing and cost.","slug":"samburu-kenya","primary_keyword":"Samburu safari","long_tail":["Samburu Special Five","Grevy''s zebra Samburu","Samburu leopard","best time to visit Samburu","Samburu vs Maasai Mara","is Samburu safe","Ewaso Ng''iro Samburu"],"search_language":"sw","local_keywords":["Samburu","Ewaso Ng''iro","punda milia wa Grevy","twiga","chui","Wasamburu","Elsa"],"hreflang":["en","sw"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-31"},"booking":{"bin":"freely_bookable","level":"L2","codes":["exercise-increased-caution","far-north-l4-carveout","crime"],"consent_flow":false,"book_suppressed":false,"note":"Kenya US L2 overall; Samburu is the SAFE MAINSTREAM safari zone but lies in northern Kenya where far-north border counties (Mandera, Wajir, Garissa; parts of Marsabit/Turkana) are US L4 Do Not Travel - Samburu is NOT among them. Route via fly-in; disclose L2 + the northern boundary. Re-verify each cycle."},"si_checklist_25":{"run_date":"2026-07-31","hits":7,"misses":15,"disregarded":3,"note":"Canonical 25-SI list; SAFARI is the launch/demo SI - primary safari not globaladv; camel safari + cultural walks = globaladv; Born Free/Elsa = deepdive; sports limited to participant; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"safari","name":"safari","status":"live","note":"Special Five, leopard, elephants"},{"si":"ultra","name":"ultra","status":"live"},{"si":"romance","name":"Romance, Marriages & Honeymoons","status":"live"},{"si":"globaladv","name":"adventure","status":"live","note":"camel safari + cultural bush walks"},{"si":"deepdive","name":"deepdive","status":"future","note":"Born Free / Elsa the lioness"},{"si":"culture","name":"culture","status":"future","note":"the Samburu people"}],"ultra":[{"name":"Saruni Samburu / Sasaab - the river''s apex stays","why_ultra":"dramatic rock-and-river suites, private guiding, camel safaris and the Special Five to yourselves","earning":"consortia/Virtuoso","virtuoso_value_add":true,"mor":"commissionable-rack","tier":"ultra","price_band":"~$900-1,800+/night"},{"name":"A private Samburu fly-in + camel + culture week","why_ultra":"exclusive-vehicle Special-Five safari + a camel-back day + a Samburu cultural immersion, privately guided","earning":"DMC/consortia","virtuoso_value_add":false,"mor":"commissionable","tier":"ultra","price_band":"on application"},{"name":"A northern-Kenya pairing (Samburu + Laikipia rhino)","why_ultra":"the Special Five + the rhino conservancies of Laikipia, private-guided fly-in throughout","earning":"DMC/consortia","virtuoso_value_add":false,"mor":"commissionable","tier":"ultra","price_band":"on application"}],"source_verified":"2026-07-31","hero":{"query":"Samburu National Reserve, Kenya"},"geo":{"lat":0.6,"lng":37.5333}}'::jsonb, 16),
  ('tarangire-tanzania', '05A', 'Tarangire National Park', 'Tanzania', 'Tanzania''s biggest elephant herds under thousand-year-old baobabs', 'live', 'verified', 'elephant', 'Tanzania — Northern Safari Circuit', '{"safari","adventure","ultra","romance","deepdive"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, 'core', '{"key_facts":["Tanzania''s elephant capital - the country''s highest elephant concentration (300+ along the Tarangire River in the dry season) and the 2nd-highest wildlife density in Tanzania after the Serengeti","Signature giant baobabs (trunks up to ~30m around) across ~2,850 km2 (Tanzania''s 6th-largest park), ~118 km SW of Arusha - the natural first/last leg of the northern circuit","550+ bird species + dry-country specials (fringe-eared oryx, gerenuk, lesser kudu); lion/leopard/cheetah; four of the Big Five (no rhino)","US L3 Reconsider Travel - terrorism concern is the Mtwara Region (far southern coast, ~700km away); bookable with L3 disclosure + consent; disclose LGBTQ+ targeting consideration; travel with a licensed operator","Best Jun-Oct (dry - game on the river); green season Nov-May lush/birdy/quieter; permits walking safaris + night drives (uncommon on the northern circuit) + balloon","Sold via Tanzanian safari DMCs + camp consortia 10-20%+ - IATAN/host-gated, CLIA has NO Africa representation; TANAPA park fees + balloon fees are pass-through; TZS (~2,633/USD, USD is the safari currency); eVisa; AMREF for evac"],"safety":{"emergency":"112 / 999","hospital":"Remote/bush - AMREF Flying Doctors (~$40 pp/30d) + travel-medical insurance; nearest referral Arusha","advisory_level":"L3","malaria":"present (lower on the high northern circuit but real) - prophylaxis + DEET advised","yellow_fever":"not required direct from US/Europe; mandatory if transiting >12h through a risk country (e.g. Kenya)","activity_note":"L3 DISCLOSE + CONSENT (terrorism concern is the far-southern Mtwara Region, ~700km away; disclose LGBTQ+ targeting - same-sex relations criminalized; travel with a licensed operator). On safari: elephant-dense driving (keep still/quiet, never between cow and calf), walking safari + night drive only with armed ranger, balloon at dawn (weight/weather limits). Remote - carry AMREF evac + insurance","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel to parts of Tanzania Tanzania FCDO advises against all but essential travel to any area within 20km of the Tanzanian border with the Cabo Delgado province of Mozambique, due to attacks by groups linked with Islamic extremism."},{"form":"against all but essential travel","text":"advises against all but essential travel to any area within 20km of the Tanzanian border with the Cabo Delgado province of Mozambique, due to attacks by groups linked with Islamic extremism."}],"url":"https://www.gov.uk/foreign-travel-advice/tanzania","read":"2026-08-19","page_updated":"2026-05-19T15:47:49+01:00"}},"timing":{"peak":"Jun-Oct (dry) - elephants + game concentrate on the Tarangire River; book 4-8 mo ahead","shoulder":"Nov + Feb-Mar (good rates, green flushes, fewer vehicles)","green":"Apr-May (long rains - lush, birdy, cheapest; some camps close)","booking_lead":"premium camps 4-8 mo for Jun-Oct; green 1-3 mo","off_season_specials":"green-season birding (550+ species breeding); calving-season combo (Tarangire + Ndutu Jan-Feb)","event_peaks":"Jul-Sep + Christmas/NY; the dry-season elephant spectacle","campaign_start":"Jun-Oct 6-9 mo out within the northern-circuit loop; green-season birding value by prior Nov-Jan; position as the 2-night elephant-and-baobab anchor, not a day-stop"},"jewels":[{"name":"The dry-season elephant spectacle","si_tag":"safari","status":"live","tier":"premier","price_band":"camp + park fees","timing":"Jun-Oct peak","draw_rank":1,"hook":"Tanzania''s largest elephant herds — hundreds gathering along the Tarangire River as the land dries — set against giant baobabs","si":"safari","blurb":"Tanzania''s largest elephant herds — hundreds gathering along the Tarangire River as the land dries — set against giant baobabs","when":"Jun-Oct peak","commission":"DMC/camp"},{"name":"Dry-country specials + big cats","si_tag":"safari","status":"live","tier":"premier","price_band":"camp + park fees","timing":"year-round; Jun-Oct best","draw_rank":2,"hook":"fringe-eared oryx, gerenuk and lesser kudu you won''t see on the plains","si":"safari","blurb":"fringe-eared oryx, gerenuk and lesser kudu you won''t see on the plains","when":"year-round; Jun-Oct best","commission":"DMC/camp"},{"name":"Walking + night safari + balloon","si_tag":"globaladv","status":"live","tier":"premier","price_band":"~$70-600/pp","timing":"Jun-Oct","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Tarangire is one of few northern-circuit parks that permits walking safaris and night drives","si":"adventure","blurb":"Tarangire is one of few northern-circuit parks that permits walking safaris and night drives","when":"Jun-Oct","commission":"DMC"},{"name":"Baobab + elephant ecology and a 550-bird list","si_tag":"deepdive","status":"future","tier":"premier","price_band":"on application","timing":"Jun-Oct","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the giant baobabs and the elephants that shape them, plus one of the northern circuit''s richest bird lists","si":"deepdive","blurb":"the giant baobabs and the elephants that shape them, plus one of the northern circuit''s richest bird lists","when":"Jun-Oct","commission":"DMC/specialist"},{"name":"A Chem Chem / Swala honeymoon","si_tag":"ultra","status":"live","tier":"luxury","price_band":"~$800-2,500+/night all-in","timing":"standing; peak 4-8 mo","draw_rank":1,"hook":"Chem Chem''s design-forward suites between Tarangire and Manyara, or Sanctuary Swala''s tented camp under the acacias by a waterhole","si":"ultra","blurb":"Chem Chem''s design-forward suites between Tarangire and Manyara, or Sanctuary Swala''s tented camp under the acacias by a waterhole","when":"standing; peak 4-8 mo","commission":"consortia/Virtuoso + DMC"},{"name":"A Tarangire honeymoon","si_tag":"romance","status":"live","tier":"luxury","price_band":"on application","timing":"Jun-Oct","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","when":"Jun-Oct","commission":"consortia/host"}],"faq":[{"q":"What''s the real risk to plan for at Tarangire?","a":"Not the parks - the advisory''s concerns are the far-southern Mtwara Region (terrorism, far away) and city petty crime, plus a flagged LGBTQ+ targeting concern travelers should weigh (Tanzanian law criminalizes same-sex relations). In Tarangire itself the risks are ordinary safari ones: stay in-vehicle near game, keep distance from elephants, malaria prophylaxis.","source":"newsweek.com","si_tag":"safety"},{"q":"Why go to Tarangire - is it worth a night?","a":"Emphatically - it has Tanzania''s biggest elephant herds and its second-densest game after the Serengeti, in a landscape of giant baobabs most of the circuit lacks; many travelers treat it as a day-stop, but a 2-night stay in the dry season is one of the northern circuit''s best-value highlights.","source":"owsl.co.tz","si_tag":"safari"},{"q":"When is the best time to visit Tarangire?","a":"The dry season, Jun-Oct, when the Tarangire River is the only water for miles and elephants, buffalo and predators concentrate along it; the green season (Nov-May) is lush, excellent for birding (550+ species) and much quieter.","source":"owsl.co.tz","si_tag":"safari"},{"q":"Do I need a visa or yellow-fever certificate for Tanzania?","a":"eVisa required - apply on the official portal before departure (~2-10 business days). Yellow fever is not required direct from the US/Europe, but is mandatory if you transit >12 h through a risk country like Kenya - key for Kenya-Tanzania combos.","source":"tanzania-specialist.com","si_tag":"safety"},{"q":"How does Tarangire fit a northern-circuit itinerary?","a":"Beautifully - it''s ~118 km SW of Arusha, so it''s the natural first or last park, paired with Lake Manyara, the Ngorongoro Crater and the Serengeti on a classic 5-8-day loop.","source":"resiliencesafaris.com","si_tag":"safari"}],"seo":{"meta_title":"Tarangire National Park Guide: Elephants, Baobabs, Best Time & Safari Costs","meta_description":"Plan a Tarangire safari - Tanzania''s elephant capital and the northern circuit''s underrated gem: the largest elephant herds in the country, ancient baobabs, 550+ birds and game second only to the Serengeti - with the US Level-3 advisory, best time (Jun-Oct), walking safaris and where to stay.","slug":"tarangire-tanzania","primary_keyword":"Tarangire National Park safari","long_tail":["Tarangire elephants baobabs","Tarangire best time to visit","Tarangire walking safari","Tarangire vs Serengeti","is Tanzania safe safari","Tarangire birding"],"search_language":"sw","local_keywords":["Tarangire","tembo","mbuyu","simba","pori"],"hreflang":["en","sw"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-08-01"},"booking":{"bin":"book_with_disclosure","level":"L3","codes":["reconsider-travel","mtwara-terrorism-carveout-far","lgbtq-targeting"],"consent_flow":true,"book_suppressed":false,"note":"Tanzania US L3 Reconsider Travel - the terrorism concern is the Mtwara Region (far southern coast), ~700km from Tarangire on the northern circuit. Bookable with L3 disclosure + consent; also disclose the LGBTQ+ targeting consideration (same-sex relations criminalized). Travel with a licensed operator. Re-verify each cycle."},"si_checklist_25":{"run_date":"2026-08-01","hits":6,"misses":16,"disregarded":3,"note":"Canonical 25-SI list; per the safari-build rule big game is safari (PRIMARY here - elephant capital), NOT globaladv; walking safari + night drive + balloon = globaladv; baobab/elephant ecology + 550 birds = deepdive; no rhino (four of Big Five); sports limited to participant; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"safari","name":"safari","status":"live","note":"big-game - highest elephant concentration in Tanzania (PRIMARY)"},{"si":"globaladv","name":"adventure","status":"live","note":"walking safari + night drive + balloon"},{"si":"ultra","name":"ultra","status":"live","note":"Chem Chem / Swala"},{"si":"romance","name":"Romance, Marriages & Honeymoons","status":"live"},{"si":"deepdive","name":"deepdive","status":"future","note":"baobab/elephant ecology + 550 birds"}],"ultra":[{"name":"Chem Chem / Little Chem Chem - the design-luxury apex","why_ultra":"a private-concession lodge between Tarangire and Manyara, walking safaris and a spa in elephant country","earning":"consortia/Virtuoso","virtuoso_value_add":true,"mor":"commissionable-rack","tier":"ultra","price_band":"~$1,200-2,500+/night"},{"name":"A private baobab-country walking week","why_ultra":"an exclusive-guide safari: walking + night drives + the elephant spectacle + a balloon dawn, from an ultra camp","earning":"DMC/consortia","virtuoso_value_add":false,"mor":"commissionable","tier":"ultra","price_band":"on application"},{"name":"The 2-night Tarangire anchor of a private northern-circuit safari","why_ultra":"Tarangire + Manyara + Ngorongoro + Serengeti, privately guided and flown, with Tarangire given the room it deserves","earning":"DMC/consortia","virtuoso_value_add":false,"mor":"commissionable","tier":"ultra","price_band":"on application"}],"source_verified":"2026-08-01","hero":{"query":"Tarangire National Park, Tanzania"},"geo":{"lat":-3.8333,"lng":36}}'::jsonb, 17),
  ('tsavo-kenya', '05A', 'Tsavo National Park (East + West)', 'Kenya', 'Kenya''s great red wilderness', 'live', 'verified', 'elephant', 'Kenya — Tsavo', '{"safari","ultra","romance","adventure","deepdive"}', '{}', '{"essential","comfort","premier","ultra"}', null, 'core', '{"key_facts":["Kenya''s largest + oldest park - Tsavo East + West ~22,000 km2 (Tsavo East 13,747 km2), ~4% of Kenya; the great red wilderness of famous terracotta ''red elephants'' (dust-bathed in iron-rich soil)","A full Big Five park (unlike Amboseli): black rhino at the Ngulia Rhino Sanctuary (Tsavo West) + the maneless Tsavo lions; Mzima Springs crystal pools with an underwater hippo/croc observation chamber; Lugard Falls (Galana River)","The legend of the Man-Eaters of Tsavo (1898 lions that halted the Kenya-Uganda railway); on the historic Nairobi-Mombasa route","The uncrowded, BETTER-VALUE big-park alternative to the Mara (whose fees rose + circuits crowd); entry $80/non-resident; road 4-5h / SGR railway / charter from Nairobi; a natural Nairobi<->coast stopover","US L2 Exercise Increased Caution (elevated risk Nairobi/urban, not Tsavo); YF NUANCE: CDC recommends the yellow-fever vaccine for Taita-Taveta County (Tsavo) - treat YF as recommended here; malaria prophylaxis advised","Sold via KATO-member Kenya safari DMCs 15-25% - IATAN/host-gated, CLIA has NO Africa representation; KWS fees non-commissionable; KES (~129/USD) + M-Pesa but safari quoted USD; eTA required; AMREF for the size/remoteness"],"safety":{"emergency":"999 / 112 / 911; Kenya Red Cross ambulance 1199 (often more reliable nationwide); AMREF Flying Doctors for bush evac","hospital":"Vast/remote - AMREF Flying Doctors (~$40 pp/30d) + travel-medical insurance; nearest referral Voi/Mombasa/Nairobi","advisory_level":"L2","malaria":"prophylaxis advised (Tsavo qualifies, chloroquine-resistant); DEET at dusk","yellow_fever":"compulsory if arriving from a risk country - AND CDC recommends the vaccine for Taita-Taveta County (Tsavo)","activity_note":"L2 disclose (elevated risk is Nairobi/urban, not Tsavo). Dangerous game at close range (lion, elephant, hippo + croc at Mzima) - stay in the vehicle, view Mzima from the boardwalk/chamber only. VASTNESS: ~22,000 km2 sparsely-roaded - breakdowns far from help, experienced operator + fuel/water + evac cover. YF recommended (Taita-Taveta). Remote - carry AMREF evac + insurance","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all travel","text":"advises against all travel to: Mandera County Tarbaj and Wajir East constituencies in Wajir County, except for Wajir Town areas of Wajir County within 60km of Kenya’s border with Somalia Garissa County - except for Garissa Town, the constituency of Lagdera and the areas of Balambala constituency which lie north and west of the main road which runs from Saka on the Tana River up to the intersection with the C81 Road Lamu County, except for Lamu Island and Manda Island FCDO advises against all but essential travel to: Garissa Town Tana River County north of the Tana River as far as the town of Saka within 15km of the east coast between the Tana River and the Galana (Athi-Galana-Sabaki) River Find out more about why FCDO advises against travel ."},{"form":"against all travel","text":"advises against all travel to: Mandera County Tarbaj and Wajir East constituencies in Wajir County, except for Wajir Town areas of Wajir County within 60km of Kenya’s border with Somalia Garissa County - except for Garissa Town, the constituency of Lagdera and the areas of Balambala constituency which lie north and west of the main road which runs from Saka on the Tana River up to the intersection with the C81 Road Lamu County, except for Lamu Island and Manda Island FCDO advises against all but essential travel to: Garissa Town Tana River County north of the Tana River as far as the town of Saka within 15km of the east coast between the Tana River and the Galana (Athi-Galana-Sabaki) River There have been frequent attacks in the north-eastern border regions, most of which were attributed to Al Shabaab."},{"form":"against all but essential travel","text":"advises against all but essential travel to: Garissa Town Tana River County north of the Tana River as far as the town of Saka within 15km of the east coast between the Tana River and the Galana (Athi-Galana-Sabaki) River Find out more about why FCDO advises against travel ."},{"form":"against all but essential travel","text":"advises against all but essential travel to: Garissa Town Tana River County north of the Tana River as far as the town of Saka within 15km of the east coast between the Tana River and the Galana (Athi-Galana-Sabaki) River There have been frequent attacks in the north-eastern border regions, most of which were attributed to Al Shabaab."}],"url":"https://www.gov.uk/foreign-travel-advice/kenya","read":"2026-08-19","page_updated":"2026-06-24T12:48:44+01:00"}},"timing":{"peak":"Jun-Oct + Jan-Feb (dry - bush thins, wildlife at water, red elephants + Mzima easiest)","shoulder":"Nov + Mar (quieter, softer rates)","green":"Apr-May (long rains - lush, birdlife, quietest, cheapest)","booking_lead":"lodges + Kenya-circuit 2-5 mo (Jun-Oct + Jan-Feb; less crunch than the Mara); shoulder/green 1-3 mo","off_season_specials":"Apr-May green-season value + birding; position as the uncrowded cheaper big park + Nairobi<->coast stopover; combine Amboseli or Mombasa/Diani beach","event_peaks":"Jun-Oct + Christmas/NY + Easter; coast-combo demand with beach season","campaign_start":"Jun-Oct + Jan-Feb 3-5 mo out; value-vs-the-Mara + green birding by prior Sep-Nov; bundle Tsavo + Amboseli + coast (southern-Kenya loop)"},"jewels":[{"name":"The red elephants of Tsavo East","si_tag":"safari","status":"live","tier":"comfort","price_band":"~$350-1,500/pp/day","timing":"Jun-Oct + Jan-Feb; dry best","draw_rank":1,"hook":"great herds of terracotta-red elephants across vast open plains, with far fewer vehicles than the Mara","si":"safari","blurb":"great herds of terracotta-red elephants across vast open plains, with far fewer vehicles than the Mara","when":"Jun-Oct + Jan-Feb; dry best","commission":"safari DMC 15-25%"},{"name":"Big Five + black rhino at Ngulia (Tsavo West)","si_tag":"safari","status":"live","tier":"comfort","price_band":"~$400-1,600/pp/day","timing":"Jun-Oct + Jan-Feb","draw_rank":2,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the maneless Tsavo lions, leopard, buffalo and elephant — plus the critically endangered black rhino of the Ngulia Rhino Sanctuary","si":"safari","blurb":"the maneless Tsavo lions, leopard, buffalo and elephant — plus the critically endangered black rhino of the Ngulia Rhino Sanctuary","when":"Jun-Oct + Jan-Feb","commission":"safari DMC 15-25%"},{"name":"Mzima Springs + the underwater chamber","si_tag":"globaladv","status":"live","tier":"essential","price_band":"~$30-120/pp","timing":"Jun-Oct + Jan-Feb","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"crystal Chyulu-fed pools alive with hippos and crocodiles, watched from a famous underwater observation chamber","si":"adventure","blurb":"crystal Chyulu-fed pools alive with hippos and crocodiles, watched from a famous underwater observation chamber","when":"Jun-Oct + Jan-Feb","commission":"DMC/camp"},{"name":"The Man-Eaters of Tsavo","si_tag":"deepdive","status":"future","tier":"essential","price_band":"on application","timing":"Jun-Oct + Jan-Feb","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"The 1898 lions that halted the Kenya–Uganda railway before Lt-Col Patterson shot them — Tsavo lies on the historic Nairobi–Mombasa route","si":"deepdive","blurb":"The 1898 lions that halted the Kenya–Uganda railway before Lt-Col Patterson shot them — Tsavo lies on the historic Nairobi–Mombasa route","when":"Jun-Oct + Jan-Feb","commission":"DMC/venue"},{"name":"A Finch Hattons / Kilaguni honeymoon","si_tag":"ultra","status":"live","tier":"premier","price_band":"~$400-1,500+/night all-in","timing":"standing; peak 2-5 mo","draw_rank":1,"hook":"Tsavo West''s grand lodges — Finch Hattons'' spring-fed luxury tents, Kilaguni Serena''s waterhole veranda under the Chyulu Hills — private, wild and quiet; honeymoon-grade","si":"ultra","blurb":"Tsavo West''s grand lodges — Finch Hattons'' spring-fed luxury tents, Kilaguni Serena''s waterhole veranda under the Chyulu Hills — private, wild and quiet; honeymoon-grade","when":"standing; peak 2-5 mo","commission":"consortia/Virtuoso + DMC"},{"name":"A Tsavo bush honeymoon","si_tag":"romance","status":"live","tier":"premier","price_band":"on application","timing":"Jun-Oct + Jan-Feb","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","when":"Jun-Oct + Jan-Feb","commission":"consortia/host"}],"faq":[{"q":"What''s the real risk to plan for in Tsavo?","a":"Vastness and remoteness. At ~22,000 km2 of sparsely-roaded wilderness, a breakdown or emergency is far from help - travel with an experienced operator and carry AMREF Flying Doctors (~$40 pp/30 days) + travel-medical insurance. Dangerous game (lion, elephant, hippo and croc at Mzima) - stay in the vehicle and follow your guide.","source":"en.wikipedia.org","si_tag":"safety"},{"q":"Do I need the yellow-fever vaccine for Tsavo?","a":"Note the nuance: while YF is otherwise only mandatory arriving from a risk country, CDC specifically recommends the yellow-fever vaccine for Taita-Taveta County, which is Tsavo - so plan for YF as recommended for this park, plus malaria prophylaxis.","source":"cdc.gov","si_tag":"safety"},{"q":"When is the best time to visit Tsavo?","a":"Jun-Oct and Jan-Feb (dry) - bush thins, wildlife concentrates at water, and the red elephants and Mzima hippos are easiest to find. The green rains bring lush scenery, birdlife and lower rates.","source":"tsavonationalparkkenya.com","si_tag":"safari"},{"q":"Tsavo East or Tsavo West - which?","a":"Tsavo East is the classic - vast open plains and the red-elephant herds; Tsavo West is more varied - volcanic terrain, Mzima Springs, and Ngulia''s black rhino. Many itineraries do both, or pair Tsavo with Amboseli or the coast.","source":"safaritravelplus.com","si_tag":"safari"},{"q":"Do I need a visa for Kenya?","a":"An eTA (Kenya replaced visas with the eTA in 2024 - apply at least 2 weeks ahead; required for all visitors). Currency is the Kenyan shilling with M-Pesa everywhere, but safari is quoted in USD.","source":"en.wikipedia.org","si_tag":"safari"}],"seo":{"meta_title":"Tsavo Safari Guide: Red Elephants, Big Five (Ngulia Rhino), Mzima Springs & Best Time","meta_description":"Plan a Tsavo safari - Kenya''s largest, oldest and least-crowded big park: the famous red elephants, a full Big Five with black rhino at Ngulia, the underwater window of Mzima Springs, the legend of the Man-Eaters, better value than the Mara - with real safety (YF-recommended), timing and cost.","slug":"tsavo-kenya","primary_keyword":"Tsavo safari","long_tail":["Tsavo red elephants","Tsavo East vs West","Ngulia rhino sanctuary","Mzima Springs Tsavo","Man-Eaters of Tsavo","best time to visit Tsavo","is Tsavo safe"],"search_language":"sw","local_keywords":["Tsavo","tembo wekundu","Chemchem za Mzima","faru mweusi","simba wa Tsavo","Maporomoko ya Lugard"],"hreflang":["en","sw"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-31"},"booking":{"bin":"freely_bookable","level":"L2","codes":["exercise-increased-caution","crime","urban-unrest"],"consent_flow":false,"book_suppressed":false,"note":"Kenya US L2 Exercise Increased Caution - elevated risk in Nairobi/urban areas, not Tsavo; safe licensed-operator safari. Disclose L2. NOTE: CDC recommends yellow-fever vaccine for Taita-Taveta County (Tsavo). Re-verify each cycle."},"si_checklist_25":{"run_date":"2026-07-31","hits":7,"misses":15,"disregarded":3,"note":"Canonical 25-SI list; SAFARI is the launch/demo SI - primary safari not globaladv; Mzima Springs/Lugard Falls/walks = globaladv; Man-Eaters/railway history = deepdive; Tsavo IS a Big Five park (Ngulia black rhino); sports limited to participant; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"safari","name":"safari","status":"live","note":"red elephants + Big Five incl. black rhino (Ngulia)"},{"si":"ultra","name":"ultra","status":"live","note":"Finch Hattons / Kilaguni"},{"si":"romance","name":"Romance, Marriages & Honeymoons","status":"live"},{"si":"globaladv","name":"adventure","status":"live","note":"Mzima Springs underwater chamber, Lugard Falls"},{"si":"deepdive","name":"deepdive","status":"future","note":"the Man-Eaters of Tsavo / railway history"}],"ultra":[{"name":"Finch Hattons Luxury Tented Camp - Tsavo''s apex stay","why_ultra":"spring-fed colonial-glamour tents under the Chyulu Hills, spa + private guiding in a vast wilderness","earning":"consortia/Virtuoso","virtuoso_value_add":true,"mor":"commissionable-rack","tier":"ultra","price_band":"~$900-1,800+/night"},{"name":"A private Tsavo East + West + Ngulia-rhino week","why_ultra":"exclusive-vehicle safari across the red-elephant plains, Mzima Springs and the black-rhino sanctuary, privately guided","earning":"DMC/consortia","virtuoso_value_add":false,"mor":"commissionable","tier":"ultra","price_band":"on application"},{"name":"A southern-Kenya bush-and-beach week (Tsavo + Amboseli + Diani)","why_ultra":"red elephants + rhino, elephants-and-Kili, then the Indian-Ocean coast, private-guided throughout","earning":"DMC/consortia","virtuoso_value_add":false,"mor":"commissionable","tier":"ultra","price_band":"on application"}],"source_verified":"2026-07-31","hero":{"query":"Tsavo National Park (East + West), Kenya"},"geo":{"lat":-2.8,"lng":38.5}}'::jsonb, 18),
