  ('komodo-indonesia', '07A', 'Komodo', 'Indonesia', 'High-current pinnacles, manta trains and dragons ashore', 'live', 'verified', 'oceanAerial', 'Komodo — Indonesia (East Nusa Tenggara)', '{"liveaboard","adventure","diveglobal","ocean"}', '{}', '{"comfort","premier"}', null, 'emerging', '{"key_facts":["SE-monsoon dry-season liveaboard sea, May-October (north 30C, optimal viz)","High-current pinnacles Castle Rock + Crystal Rock (reef-hook dives)","Manta Alley / Manta Point manta cleaning + feeding sites","Komodo dragons ashore (Komodo NP) - the land add-on; fleet incl. Komodo Aggressor (reseller line held)","Advisory: State L2 (reissued 30 Apr 2025; only Papua L4 carve-outs; Komodo/NTT clear - the ''Poso'' carve-out was an error, removed); FCDO 7km Mt Lewotobi exclusion on Flores + Bali/Flores flight disruption (Labuan Bajo gateway is on Flores); chamber at Siloam Labuan Bajo (2018), Sanglah Bali fallback - verified 2026-08-09"],"safety":{"emergency":"112 / 118 ambulance (verify)","hospital":"Siloam Hospitals Labuan Bajo (Flores); Sanglah General Hospital, Denpasar Bali for serious care (verify)","hyperbaric":"Hyperbaric oxygen chamber at Siloam Hospitals Labuan Bajo (Flores) since 13 Oct 2018, first in East Nusa Tenggara (8-patient); fallback Sanglah General Hospital, Denpasar Bali, ~1.5h by air - confirm 24h readiness via operator/DAN (source: wetfrogdivers.com + komodoresort.com, 2026-08-09)","advisory_level":"L2","regional_hazard":"FCDO advises against all travel within 7km of the crater of Mount Lewotobi Laki-Laki on Flores (erupted 17 Jun 2025, alert level 4, mud/debris-flow warning) + disruption to Bali/Flores flights; Labuan Bajo (Komodo gateway) is on Flores, outside the zone but exposed to flight disruption (gov.uk/foreign-travel-advice/indonesia/regional-risks, 2026-08-09)","no_fly_after_diving":"18-24h (DAN)","malaria":"present in parts of Flores/NTT (verify)","yellow_fever":"only if arriving from an endemic country","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all travel","text":"advises against all travel FCDO advises against all travel to a number of volcanoes in Indonesia: Mount Lewotobi Laki-Laki, on Flores Island, East Nusa Tenggara Province to within 7km of the crater Mount Sinabung, Karo Regency, North Sumatra to within 5km of the crater Mount Marapi, West Sumatra to within 3km of the crater Mount Semeru, Lumajang Regency, East Java to within 5km of the crater in the south-east of Mount Semura to within 500m from any riverbank of the Besuk Kobokan river for 13km from the crater Mount Ruang, Northern Sulawesi to within 7km of the crater Mount Ibu, North Maluku Province to within 7km of the crater See more details about why FCDO advises against travel ."},{"form":"against all travel","text":"advises against all travel to within 7km of the crater of Mount Lewotobi Laki-Laki on Flores Island, East Nusa Tenggara province."},{"form":"against all travel","text":"advises against all travel to within 5km of the crater of Mount Sinabung in Karo Regency, North Sumatra."},{"form":"against all travel","text":"advises against all travel to within 3km of the crater of Mount Marapi in West Sumatra."},{"form":"against all travel","text":"advises against all travel to: within 5 km of the crater of Mount Semeru in Lumajang Regency, East Java the south-east area of Mount Semeru along the Besuk Kobokan river, approximately 13km from the crater, and 500m from any Besuk Kobokan riverbank These areas align with exclusion zones put in place by the local authorities."},{"form":"against all travel","text":"advises against all travel to within 7km of the crater of Mount Ruang in Northern Sulawesi."},{"form":"against all travel","text":"advises against all travel to within 7km of the crater of Mount Ibu in North Maluku Province."}],"url":"https://www.gov.uk/foreign-travel-advice/indonesia","read":"2026-08-19","page_updated":"2026-08-16T12:31:33+01:00"}},"timing":{"peak":"May-Oct (SE monsoon dry - north 30C, optimal viz)","shoulder":"Apr & Nov (monsoon turn)","green":"Dec-Mar (NW monsoon wetter; boats reposition to Raja Ampat)","booking_lead":"peak dry-season preferred vessels ~3-9 months; shoulder nearer term; confirm per-vessel","off_season_specials":"monsoon-turn shoulder weeks lower demand","event_peaks":"May-Oct dry season is the demand window; manta sites peak within it","campaign_start":"dry-season fire Jan-Feb (inverse of the Raja Ampat campaign)"},"jewels":[{"name":"Castle Rock","si_tag":"liveaboard","status":"live","tier":"premier","hook":"high-current pinnacle, schooling pelagics, reef-hook dive","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/indonesia","timing":"year-round","timing_type":"ALWAYS-ON","si":"liveaboard","blurb":"high-current pinnacle, schooling pelagics, reef-hook dive","when":"year-round","commission":"fleet-direct (Aggressor)"},{"name":"Crystal Rock","si_tag":"liveaboard","status":"live","tier":"premier","hook":"sister pinnacle, current-swept","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/indonesia","timing":"May-Oct","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"sister pinnacle, current-swept","when":"May-Oct","commission":"fleet-direct"},{"name":"Manta Alley","si_tag":"liveaboard","status":"live","tier":"premier","hook":"southern manta cleaning/feeding site","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/indonesia","si":"liveaboard","blurb":"southern manta cleaning/feeding site","commission":"fleet-direct"},{"name":"Manta Point","si_tag":"liveaboard","status":"live","tier":"comfort","hook":"manta cleaning station","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/indonesia","si":"liveaboard","blurb":"manta cleaning station","commission":"fleet-direct"},{"name":"Sangeang Volcano sites","si_tag":"liveaboard","status":"live","tier":"premier","hook":"volcanic-slope diving, bubbling sand","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/indonesia","timing":"May-Oct","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"volcanic-slope diving, bubbling sand","when":"May-Oct","commission":"fleet-direct"},{"name":"Gili Lawa Laut","si_tag":"liveaboard","status":"live","tier":"comfort","hook":"northern reef and ridge","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/indonesia","timing":"May-Oct","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"northern reef and ridge","when":"May-Oct","commission":"fleet-direct"},{"name":"Gili Banta","si_tag":"liveaboard","status":"live","tier":"premier","hook":"outer current site","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/indonesia","timing":"May-Oct","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"outer current site","when":"May-Oct","commission":"fleet-direct"},{"name":"Moyo Island","si_tag":"liveaboard","status":"live","tier":"comfort","hook":"reposition-leg reef","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/indonesia","timing":"May-Oct","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"reposition-leg reef","when":"May-Oct","commission":"fleet-direct"},{"name":"Satonda","si_tag":"liveaboard","status":"live","tier":"comfort","hook":"crater-lake island stop","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/indonesia","timing":"May-Oct","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"crater-lake island stop","when":"May-Oct","commission":"fleet-direct"},{"name":"Padar","si_tag":"liveaboard","status":"live","tier":"comfort","hook":"three-bay viewpoint island","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/indonesia","timing":"May-Oct","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"three-bay viewpoint island","when":"May-Oct","commission":"fleet-direct"},{"name":"Central Komodo current-pinnacle route","si_tag":"liveaboard","status":"live","tier":"premier","hook":"Castle/Crystal Rock + Gili Lawa, dry-season","bookable_category":"liveaboard week","source":"https://www.liveaboard.com/diving/indonesia","timing":"May-Oct","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"Castle/Crystal Rock + Gili Lawa, dry-season","when":"May-Oct","commission":"fleet-direct (Aggressor)"},{"name":"Southern manta route","si_tag":"liveaboard","status":"live","tier":"premier","hook":"Manta Alley + southern reefs","bookable_category":"liveaboard week","source":"https://www.liveaboard.com/diving/indonesia","si":"liveaboard","blurb":"Manta Alley + southern reefs","commission":"fleet-direct (Aggressor)"},{"name":"Komodo National Park dragon walk + Padar","si_tag":"globaladv","status":"future","tier":"comfort","hook":"ranger-guided dragons on Komodo/Rinca + Padar viewpoint","bookable_category":"liveaboard-included park day / DMC","source":"https://www.liveaboard.com/diving/indonesia","timing":"May-Oct","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"adventure","blurb":"ranger-guided dragons on Komodo/Rinca + Padar viewpoint","when":"May-Oct","commission":"DMC (park fee pass-through)"}],"faq":[{"q":"What is the current advisory for Komodo, and how do I dive it responsibly?","a":"The U.S. State Department places Indonesia at Level 2 - Exercise Increased Caution (reissued 30 April 2025). Its only Level 4 (Do Not Travel) carve-outs are Central Papua (Papua Tengah) and Highland Papua (Papua Pegunungan), for civil unrest; Komodo, in East Nusa Tenggara, sits well apart from both. The material regional flag comes from the UK FCDO, which advises against all travel within 7 km of the crater of Mount Lewotobi Laki-Laki on Flores - a volcano that erupted on 17 June 2025, holds Indonesia''s highest alert (level 4), and carries mud/debris-flow warnings plus disruption to flights to and from Bali and Flores. Because Labuan Bajo, Komodo''s gateway, is on Flores, build slack into flight connections and confirm status before travel. Carry DAN membership plus separate dive-accident insurance and observe an 18-24 hour no-fly window after diving.","source":"travel.state.gov/en/international-travel/travel-advisories/indonesia.html + gov.uk/foreign-travel-advice/indonesia/regional-risks (both accessed 2026-08-09)","si_tag":"safety"},{"q":"Is there a recompression chamber, and how remote is care?","a":"Since 13 October 2018 Komodo''s gateway has had its own chamber: a hyperbaric oxygen chamber at Siloam Hospitals Labuan Bajo (Flores), the first in East Nusa Tenggara and an eight-patient chamber, so divers no longer have to be flown to Bali first. The fallback remains Sanglah General Hospital in Denpasar, Bali, roughly 1.5 hours by air. Confirm the Labuan Bajo chamber''s 24-hour readiness on your dates with the operator or DAN, and note that the Mount Lewotobi flight disruption can affect the Bali evacuation leg. Komodo''s currents put a premium on conservative profiles and dive-accident insurance.","source":"wetfrogdivers.com/first-hyperbaric-oxygen-chamber-in-komodo + komodoresort.com (accessed 2026-08-09)","si_tag":"safety"},{"q":"When is the best time to dive Komodo?","a":"May-October, the Southeast Monsoon dry season, is the popular liveaboard window, with northern waters at 30C and optimal visibility. The cooler southern sites (Manta Alley area) carry more nutrient and colder water; route and month are set by the operator''s north/south plan.","source":"liveaboard.com/diving/indonesia","si_tag":"planning"},{"q":"Where do I see mantas in Komodo?","a":"Manta Alley and Manta Point are the named manta sites - cleaning stations and feeding aggregations in current.","source":"liveaboard.com/diving/indonesia","si_tag":"liveaboard"},{"q":"What conditions and certification should I plan for?","a":"Castle Rock and Crystal Rock are high-current pinnacle dives suited to experienced divers with reef hooks; sheltered sites and the Sangeang volcanic slopes suit a wider range with a guide. Nitrox is standard on liveaboards. Dive within your certification and the briefing.","source":"liveaboard.com/diving/indonesia","si_tag":"liveaboard"},{"q":"Can I see the Komodo dragons on the same trip?","a":"Yes - Komodo National Park pairs the diving with ranger-guided dragon walks on Komodo and Rinca and the Padar viewpoint; most liveaboards include a park day.","source":"liveaboard.com/diving/indonesia","si_tag":"globaladv"},{"q":"How far ahead do Komodo liveaboards book?","a":"Peak dry-season (May-October) weeks on preferred vessels fill earliest; hold roughly 3-9 months out for peak windows, nearer term for the shoulder. Confirm per-vessel lead times with the operator.","source":"liveaboard.com/diving/indonesia","si_tag":"planning"}],"seo":{"meta_title":"Komodo Liveaboard Diving, Indonesia: Currents, Mantas, Dragons","meta_description":"Komodo dive-liveaboard guide - Castle Rock and Crystal Rock currents, Manta Alley, the May-October dry season, operators, the dragons ashore, and safety.","slug":"komodo-indonesia","primary_keyword":"Komodo liveaboard diving","long_tail":["Castle Rock Komodo","Manta Alley Komodo","Komodo dive season","Komodo dragons dive trip","Komodo liveaboard operators"],"search_language":"id (restated, not machine-translated)","local_keywords":["menyelam Komodo","liveaboard Komodo","Manta Alley"],"hreflang":["en","id"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-08-09"},"booking":{"bin":"freely bookable (L2)","level":"L2 (Exercise Increased Caution)","codes":["L2"],"consent_flow":false,"note":"US State Dept Level 2, reissued 30 Apr 2025, accessed 2026-08-09 (travel.state.gov/en/.../indonesia.html). ONLY Level 4 (Do Not Travel) carve-outs: Central Papua (Papua Tengah) + Highland Papua (Papua Pegunungan) for civil unrest; Komodo (East Nusa Tenggara) sits well apart. CORRECTION: the earlier ''Central Sulawesi/Poso'' carve-out was in error and is removed. FCDO regional-risks cross-check (gov.uk/foreign-travel-advice/indonesia/regional-risks, accessed 2026-08-09): advises against all travel within 7km of the crater of Mount Lewotobi Laki-Laki on Flores (erupted 17 Jun 2025, alert level 4, mud/debris-flow warning) + disruption to Bali/Flores flights. Labuan Bajo (Komodo gateway) is on Flores, outside the 7km zone but exposed to flight disruption - stricter access flag, not a Komodo booking bar."},"si_checklist_25":{"run_date":"2026-08-09","hits":4,"misses":18,"disregarded":3,"note":"Liveaboard-diving scope; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"liveaboard","name":"liveaboard","status":"live"},{"si":"globaladv","name":"adventure","status":"future"},{"si":"diveglobal","name":"diveglobal","status":"future"},{"si":"ocean","name":"ocean","status":"future"}],"ultra":[{"name":"Private-charter luxury phinisi (Dewi Nusantara-class) + Bali pre/post","why_ultra":"the Komodo ultra pull is a private luxury-phinisi or full-boat charter paired with Bali","earning":"held Aggressor reseller line; verify luxury-phinisi charter terms","virtuoso_value_add":"verify - not documented","mor":"commission-on-net; no net-rate resale markup","source":"handoff/LIVEABOARD-OPERATOR-GRID-2026-08-09.md"}],"source_verified":"2026-08-09","hero":{"query":"Komodo, Indonesia"},"geo":{"lat":-8.55,"lng":119.48}}'::jsonb, 4),
  ('maldives', '07A', 'Maldives', 'Maldives', '*If it''s channel drifts, manta trains and warm clear', 'live', 'verified', 'oceanAerial', 'Maldives — Indian Ocean', '{"liveaboard","diveglobal","tropical","ocean"}', '{"tropical"}', '{"comfort","premier"}', null, 'core', '{"key_facts":["Two monsoons: NE dry (Dec-May) clear-water pelagics; SW (Jun-Nov) manta/whale-shark plankton season","Hanifaru Bay (Baa) manta/whale-shark aggregation Jun-Oct, snorkel-only core","Channel (kandu) + thila diving across North/South Male, Ari, Baa, Vaavu, Fuvahmulah","Fleet: Aggressor (Maldives Aggressor II), Explorer Ventures, Emperor (x5), Master, Scubaspa, Carpe Diem - TWW holds Aggressor + Explorer lines","Advisory: State L2 due to terrorism (no carve-out; remote-island response-time caveat; FCDO no advise-against but flags indiscriminate risk); 5 chambers - Bandos nearest Male, Kuredu 24h north - verified 2026-08-09"],"safety":{"emergency":"102 ambulance / 119 police (verify)","hospital":"Malé (IGMH/ADK) main hospitals (verify)","hyperbaric":"5 operational chambers: Bandos (North Male, ~15 min speedboat from Male - nearest to departure, largest/longest-operating); Kuredu (Lhaviyani, 24h on-call, only chamber in the north); Kuramathi (Ari); Kandima (Dhaalu); ADK Male. Evac by speedboat/seaplane - confirm route chamber (source: masterliveaboards.com/faq/maldives + kureduclinic.com, 2026-08-09)","advisory_level":"L2","no_fly_after_diving":"18-24h (DAN)","malaria":"none (verify)","yellow_fever":"none required","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/maldives","read":"2026-08-19","page_updated":"2026-08-12T11:35:58+01:00"}},"timing":{"peak":"Dec-Apr (NE monsoon dry - clearest water, calmest seas, tropical high season)","shoulder":"May & Nov (monsoon turn)","green":"Jun-Nov (SW monsoon - greener water but manta/whale-shark season)","booking_lead":"peak NE-season + manta-season preferred vessels ~3-9 months; shoulder nearer term; confirm per-vessel","off_season_specials":"monsoon-turn shoulder weeks lower demand","event_peaks":"Jun-Oct SW-monsoon manta/whale-shark (Hanifaru)","campaign_start":"manta-season fire Mar-Apr; clear-water NE-season fire Aug-Sep"},"jewels":[{"name":"Hanifaru Bay (Baa Atoll)","si_tag":"liveaboard","status":"live","tier":"premier","hook":"Jun-Oct manta/whale-shark aggregation, snorkel-only core","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/maldives","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"Jun-Oct manta/whale-shark aggregation, snorkel-only core","when":"Dec-Apr","commission":"fleet-direct (Aggressor/Explorer)"},{"name":"Maaya Thila (Ari)","si_tag":"liveaboard","status":"live","tier":"comfort","hook":"classic pinnacle, night diving","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/maldives","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"classic pinnacle, night diving","when":"Dec-Apr","commission":"fleet-direct"},{"name":"Donkalo Thila","si_tag":"liveaboard","status":"live","tier":"comfort","hook":"manta cleaning-station thila","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/maldives","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"manta cleaning-station thila","when":"Dec-Apr","commission":"fleet-direct"},{"name":"Maavaru Kandu","si_tag":"liveaboard","status":"live","tier":"premier","hook":"current-driven channel drift","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/maldives","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"current-driven channel drift","when":"Dec-Apr","commission":"fleet-direct"},{"name":"Dhonfanu Thila","si_tag":"liveaboard","status":"live","tier":"comfort","hook":"Baa Atoll pinnacle","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/maldives","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"Baa Atoll pinnacle","when":"Dec-Apr","commission":"fleet-direct"},{"name":"Dhigali Haa (Baa)","si_tag":"liveaboard","status":"live","tier":"premier","hook":"protected marine-area pinnacle","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/maldives","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"protected marine-area pinnacle","when":"Dec-Apr","commission":"fleet-direct"},{"name":"Gahaa Kandu","si_tag":"liveaboard","status":"live","tier":"premier","hook":"channel drift","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/maldives","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"channel drift","when":"Dec-Apr","commission":"fleet-direct"},{"name":"Thoondu Point (Fuvahmulah)","si_tag":"liveaboard","status":"live","tier":"premier","hook":"southern atoll, tiger/thresher shark water","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/maldives","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"southern atoll, tiger/thresher shark water","when":"Dec-Apr","commission":"fleet-direct"},{"name":"South Ari Atoll whale-shark zone","si_tag":"liveaboard","status":"live","tier":"premier","hook":"year-round whale sharks","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/maldives","si":"liveaboard","blurb":"year-round whale sharks","commission":"fleet-direct"},{"name":"Vaavu (Felidhoo) Atoll channel dives","si_tag":"liveaboard","status":"live","tier":"premier","hook":"Vaavu channel + shark-night diving","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/maldives","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"Vaavu channel + shark-night diving","when":"Dec-Apr","commission":"fleet-direct"},{"name":"North Male Atoll channel & manta dives","si_tag":"liveaboard","status":"live","tier":"comfort","hook":"the classic first-week atoll","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/maldives","si":"liveaboard","blurb":"the classic first-week atoll","commission":"fleet-direct"},{"name":"NE-monsoon central-atoll route (Dec-Apr)","si_tag":"liveaboard","status":"live","tier":"premier","hook":"clear-water channel-pelagic week","bookable_category":"liveaboard week","source":"https://www.liveaboard.com/diving/season-calendar/best-time-to-dive-in-the-maldives","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"clear-water channel-pelagic week","when":"Dec-Apr","commission":"fleet-direct (Aggressor/Explorer)"},{"name":"SW-monsoon manta route (Jun-Oct)","si_tag":"liveaboard","status":"live","tier":"premier","hook":"Baa/Hanifaru manta-season week","bookable_category":"liveaboard week","source":"https://www.liveaboard.com/diving/season-calendar/best-time-to-dive-in-the-maldives","si":"liveaboard","blurb":"Baa/Hanifaru manta-season week","commission":"fleet-direct (Aggressor/Explorer)"}],"faq":[{"q":"What is the current advisory for the Maldives, and how do I dive it responsibly?","a":"The U.S. State Department places the Maldives at Level 2 - Exercise Increased Caution, due to terrorism, with no sub-national carve-out (accessed 2026-08-09). State adds that attacks may occur on remote islands, which can lengthen the response time of authorities - worth weighing on a liveaboard far from Male. The UK FCDO advises against no travel but says terrorist attacks cannot be ruled out and could be indiscriminate; the stricter baseline (State Level 2) sets the posture. Carry DAN membership plus separate dive-accident insurance (liveaboard.com requires divers to independently hold it) and observe an 18-24 hour no-fly window after diving.","source":"travel.state.gov/en/international-travel/travel-advisories/maldives.html + gov.uk/foreign-travel-advice/maldives/safety-and-security (both accessed 2026-08-09)","si_tag":"safety"},{"q":"Is there a recompression chamber, and how remote is care?","a":"Master Liveaboards'' Maldives FAQ names five operational recompression chambers, with the largest and longest-operating on Bandos Island in North Male Atoll, 15 minutes by speedboat from Male - the closest to a Male departure. Others sit at Kuramathi (North Ari), Kuredu (Lhaviyani, the only chamber in the northern Maldives, with a clinic reporting operators on call 24 hours), Kandima (Dhaalu) and ADK Hospital in Male. Recompression treatment is likely to involve evacuation by private speedboat or seaplane, so confirm the chamber nearest your route and its readiness on your dates with the operator or DAN.","source":"masterliveaboards.com/faq/maldives + kureduclinic.com (accessed 2026-08-09)","si_tag":"safety"},{"q":"When is the best time to dive the Maldives?","a":"December-May is the dry northeast-monsoon window - calmer seas, clearer water (15-20 m+), best for channel pelagics. June-November is the southwest monsoon: greener water but the manta and whale-shark season. Water stays 26-29C year-round.","source":"liveaboard.com/diving/season-calendar/best-time-to-dive-in-the-maldives","si_tag":"planning"},{"q":"When and where do I see mantas and whale sharks?","a":"June-October in the southwest monsoon, with Hanifaru Bay in Baa Atoll the signature aggregation site (snorkel-only in the protected core); South Ari Atoll holds whale sharks year-round.","source":"liveaboard.com/diving/maldives","si_tag":"liveaboard"},{"q":"Which atolls does a liveaboard week cover?","a":"Central-atoll routes work North/South Male, Ari, Vaavu and Baa; southern and specialist routes reach Fuvahmulah (tiger and thresher sharks) and Huvadhoo. Route choice tracks the monsoon - central-atoll clear-water weeks in the northeast season, manta routes in the southwest.","source":"liveaboard.com/diving/maldives","si_tag":"liveaboard"},{"q":"What conditions and certification should I plan for?","a":"Channel (kandu) dives are current-driven drift dives suited to experienced divers; thila pinnacles and lagoon sites suit a wider range with a guide. Nitrox is standard on liveaboards for the multi-day profile. Dive within your certification and the briefing.","source":"liveaboard.com/diving/maldives","si_tag":"liveaboard"},{"q":"How far ahead do Maldives liveaboards book?","a":"Northeast-season (Dec-Apr) clear-water weeks and manta-season (Jun-Oct) berths on preferred vessels fill earliest; hold roughly 3-9 months out for peak windows, nearer term for shoulder. Confirm per-vessel lead times with the operator.","source":"liveaboard.com/diving/maldives","si_tag":"planning"}],"seo":{"meta_title":"Maldives Liveaboard Diving: Mantas, Channels & Season","meta_description":"The Maldives dive-liveaboard chain - Hanifaru manta season, channel-and-thila drifts across Ari/Baa/Vaavu, monsoon season split, operators and safety.","slug":"maldives","primary_keyword":"Maldives liveaboard diving","long_tail":["Hanifaru Bay manta season","Maldives dive season monsoon","Maaya Thila","South Ari whale shark","Maldives liveaboard operators"],"search_language":"dv (restated, not machine-translated)","local_keywords":["ޑައިވިން ދިވެހިރާއްޖެ"],"hreflang":["en","dv"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-08-09"},"booking":{"bin":"freely bookable (L2)","level":"L2 (Exercise Increased Caution)","codes":["L2"],"consent_flow":false,"note":"US State Dept Level 2 due to terrorism, no sub-national carve-out, accessed 2026-08-09 (travel.state.gov/en/.../maldives.html). State: attacks may occur on remote islands, which can lengthen the response time of authorities (material for liveaboards). FCDO cross-check (gov.uk/foreign-travel-advice/maldives, accessed 2026-08-09): advises against no travel; terrorist attacks cannot be ruled out and could be indiscriminate. Stricter baseline (State L2) drives posture."},"si_checklist_25":{"run_date":"2026-08-09","hits":4,"misses":18,"disregarded":3,"note":"Liveaboard-diving scope; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"liveaboard","name":"liveaboard","status":"live"},{"si":"diveglobal","name":"diveglobal","status":"future"},{"si":"tropical","name":"tropical","status":"future"},{"si":"ocean","name":"ocean","status":"future"}],"ultra":[{"name":"Private-charter luxury liveaboard (Scubaspa/Carpe Diem/full-boat Aggressor/Master) or dive + overwater-villa combo","why_ultra":"the Maldives ultra pull is a private charter or a liveaboard-plus-resort pairing","earning":"held reseller line for Aggressor/Explorer; verify luxury-vessel charter terms","virtuoso_value_add":"verify - not documented","mor":"commission-on-net; no net-rate resale markup","source":"handoff/LIVEABOARD-OPERATOR-GRID-2026-08-09.md"}],"source_verified":"2026-08-09","hero":{"query":"Maldives, Maldives"},"geo":{"lat":3.2028,"lng":73.2207}}'::jsonb, 5)
